Left.Text:
// internal/groomer/auth.go
// lookupUser finds the owner signing in. The password plugin calls its
// identifier an email and posts it as "email"; this app has no email
// anywhere, so what arrives is a username, lowercased and trimmed.
// There is no scope: a visitor signing in is owned by nobody yet.
func lookupUser(database *gorm.DB) func(
	context.Context, string,
) (int64, string, error) {
	return func(ctx context.Context, username string) (int64, string, error) {
		var user User
		err := database.WithContext(ctx).
			Where("username = ?", username).First(&user).Error
		if errors.Is(err, gorm.ErrRecordNotFound) {
			return 0, "", sql.ErrNoRows
		}
		return user.ID, user.PasswordHash, err
	}
}

