// internal/groomer/bookings.go
// Cancel frees the booking's time. A booking already in the past
// cannot be cancelled: it happened, or it was a no-show.
func (bookings *Bookings) Cancel(ctx context.Context, booking Booking) error {
	if !booking.StartsAt.After(bookings.now()) {
		return op.Conflict{Message: "This appointment has already started."}
	}
	if booking.Cancelled {
		return nil
	}
	return bookings.database.WithContext(ctx).Model(&booking).
		Select("Cancelled").Updates(Booking{Cancelled: true}).Error
}

Right.Text:
// internal/groomer/ledger.go
// CancelBooking frees a booking's time for someone else. Cancelling
// one already cancelled changes nothing, so a double click is
// harmless.
func (salon *Salon) CancelBooking(ctx context.Context, id int64) error {
	cancelled := salon.now().UTC()
	result := salon.database.WithContext(ctx).Model(&Booking{}).
		Where("id = ? AND cancelled_at IS NULL", id).
		Select("CancelledAt").Updates(map[string]any{
		"CancelledAt": &cancelled,
	})
	if result.Error != nil {
		return result.Error
	}
	if result.RowsAffected == 1 {
		return nil
	}
	_, err := salon.Booking(ctx, id)
	return err
}

