// Cancel frees a booking's slot. Cancelling twice is not an error: the
// second press finds the work already done.
func (salon salon) Cancel(ctx context.Context, id int64,
	now time.Time) error {
	if _, err := salon.Booking(ctx, id); err != nil {
		return err
	}
	stamp := now.UTC()
	return salon.database.WithContext(ctx).Model(&Booking{ID: id}).
		Where("cancelled_at IS NULL").Select("CancelledAt").
		Updates(Booking{CancelledAt: &stamp}).Error
}

