// internal/groomer/agenda.go
// List is the bookings on one of the owner's lists: upcoming soonest
// first, the other two most recent first.
func (bookings *Bookings) List(
	ctx context.Context, agenda Agenda,
) ([]Booking, error) {
	var rows []Booking
	query := agendaQuery(bookings.database.WithContext(ctx), agenda,
		bookings.now().UTC())
	err := query.Find(&rows).Error
	return rows, err
}

func agendaQuery(query *gorm.DB, agenda Agenda, now time.Time) *gorm.DB {
	switch agenda {
	case AgendaPast:
		return query.Where("cancelled = ? AND ends_at <= ?", false, now).
			Order("starts_at DESC").Limit(agendaLimit)
	case AgendaCancelled:
		return query.Where("cancelled = ?", true).
			Order("starts_at DESC").Limit(agendaLimit)
	default:
		return query.Where("cancelled = ? AND ends_at > ?", false, now).
			Order("starts_at")
	}
}

