Left.Text:
// internal/groomer/bookings.go
// Slots is every start time on day that fits service around the
// bookings already made and is not yet past.
func (salon salon) Slots(ctx context.Context, service Service,
	day, now time.Time) ([]time.Time, error) {
	database := salon.database.WithContext(ctx)
	week, err := weekOf(database)
	if err != nil {
		return nil, err
	}
	taken, err := takenOn(database, day)
	if err != nil {
		return nil, err
	}
	hours := week[day.Weekday()]
	return freeSlots(hours, day, service.Minutes, taken, now), nil
}

// takenOn is every booking still standing that touches day.
func takenOn(database *gorm.DB, day time.Time) ([]Booking, error) {
	var taken []Booking
	err := database.Where("cancelled_at IS NULL AND starts_at < ? "+
		"AND ends_at > ?", day.AddDate(0, 0, 1).UTC(), day.UTC()).
		Find(&taken).Error
	return taken, err
}

// freeSlots is the arithmetic behind Slots. The salon has one grooming
// table, so any overlap with a standing booking rules a slot out.
func freeSlots(hours OpeningDay, day time.Time, minutes int,
	taken []Booking, now time.Time) []time.Time {
	if !hours.Open || minutes <= 0 {
		return nil
	}
	length := time.Duration(minutes) * time.Minute
	opens, closes := atMinute(day, hours.OpensAt), atMinute(day,
		hours.ClosesAt)
	var free []time.Time
	for start := opens; !start.Add(length).After(closes); start =
		start.Add(slotStep) {
		if start.Before(now) || overlaps(start, start.Add(length),
			taken) {
			continue
		}
		free = append(free, start)
	}
	return free
}

func overlaps(start, end time.Time, taken []Booking) bool {
	return slices.ContainsFunc(taken, func(booking Booking) bool {
		return booking.StartsAt.Before(end) && booking.EndsAt.After(start)
	})
}

Right.Text:
// internal/groomer/bookings.go
// OpenTimes is every start time on day that service still fits into:
// inside opening hours, after now, and clear of every booking.
func (bookings Bookings) OpenTimes(ctx context.Context, service Service,
	day, now time.Time) ([]time.Time, error) {
	hour, err := bookings.hours.On(ctx, day)
	if err != nil || !hour.Open {
		return nil, err
	}
	taken, err := bookings.takenOn(ctx, day)
	if err != nil {
		return nil, err
	}
	length := time.Duration(service.Minutes) * time.Minute
	closes := atMinute(day, hour.ClosesAt)
	var open []time.Time
	for start := atMinute(day, hour.OpensAt); !start.Add(length).
		After(closes); start = start.Add(slotStep) {
		if start.After(now) && !overlaps(taken, start, start.Add(length)) {
			open = append(open, start)
		}
	}
	return open, nil
}

func (bookings Bookings) takenOn(ctx context.Context, day time.Time) (
	[]Booking, error) {
	var taken []Booking
	err := bookings.database.WithContext(ctx).
		Where("cancelled = ? AND starts_at < ? AND ends_at > ?", false,
			day.AddDate(0, 0, 1).UTC(), day.UTC()).Find(&taken).Error
	return taken, err
}

func overlaps(taken []Booking, starts, ends time.Time) bool {
	for _, booking := range taken {
		if booking.StartsAt.Before(ends) && booking.EndsAt.After(starts) {
			return true
		}
	}
	return false
}

