// internal/groomer/salon.go
// check reads the length and refuses what the salon cannot offer.
func (details serviceDetails) check() (int, error) {
	problems := map[string]string{}
	if strings.TrimSpace(details.Name) == "" {
		problems["Name"] = "Enter the service's name."
	}
	minutes, err := strconv.Atoi(strings.TrimSpace(details.Minutes))
	if err != nil || minutes < 5 || minutes > 480 {
		problems["Minutes"] = "Enter a length from 5 to 480 minutes."
	}
	if details.PriceMinor < 0 {
		problems["Price"] = "A price cannot be below zero."
	}
	if len(problems) > 0 {
		return 0, op.Invalid{Fields: problems}
	}
	return minutes, nil
}

// UpdateService changes a service. Bookings already made keep the name
// and length they were made with.
func (salon *salon) UpdateService(
	ctx context.Context, id int64, details serviceDetails,
) error {
	minutes, err := details.check()
	if err != nil {
		return err
	}
	service, err := salon.Service(ctx, id)
	if err != nil {
		return err
	}
	return salon.rows(ctx).Model(&service).
		Select("Name", "Description", "Minutes", "PriceMinor", "Offered").
		Updates(Service{
			Name:        strings.TrimSpace(details.Name),
			Description: strings.TrimSpace(details.Description),
			Minutes:     minutes, PriceMinor: details.PriceMinor,
			Offered: details.Offered,
		}).Error
}

