// internal/groomer/services.go
// Change rewrites a service. Bookings already made keep the times they
// were given, even when the service now runs longer.
func (services Services) Change(ctx context.Context, id int64,
	input ServiceInput) error {
	input, err := input.checked()
	if err != nil {
		return err
	}
	result := services.database.WithContext(ctx).Model(&Service{ID: id}).
		Select("Name", "Description", "Minutes", "PriceMinor", "Offered").
		Updates(map[string]any{"Name": input.Name,
			"Description": input.Description, "Minutes": input.Minutes,
			"PriceMinor": input.PriceMinor, "Offered": input.Offered})
	if result.Error != nil {
		return result.Error
	}
	if result.RowsAffected == 0 {
		return op.NotFound{}
	}
	return nil
