// checked trims input and refuses what a booking page could not show.
func (input ServiceInput) checked() (ServiceInput, error) {
	input.Name = strings.TrimSpace(input.Name)
	input.Description = strings.TrimSpace(input.Description)
	fields := map[string]string{}
	if input.Name == "" || utf8.RuneCountInString(input.Name) > 60 {
		fields["Name"] = "Enter a name of up to 60 characters."
	}
	if utf8.RuneCountInString(input.Description) > 400 {
		fields["Description"] = "Keep the description to 400 characters."
	}
	if input.Minutes < serviceMinutesStep ||
		input.Minutes > serviceMinutesMost ||
		input.Minutes%serviceMinutesStep != 0 {
		fields["Minutes"] = "Pick how long the service takes."
	}
	if input.PriceMinor < 0 {
		fields["Price"] = "Enter a price of zero or more."
	}
	if len(fields) > 0 {
		return input, op.Invalid{Fields: fields}
	}
	return input, nil
}

