// internal/groomer/appointments.go
// List is one view of the book: upcoming soonest first, past and
// cancelled most recent first.
func (bookings Bookings) List(ctx context.Context, view string,
	now time.Time) ([]BookingLine, error) {
	query := bookings.lines(ctx)
	switch view {
	case showPast:
		query = query.Where("bookings.cancelled = ? AND "+
			"bookings.ends_at <= ?", false, now.UTC()).
			Order("bookings.starts_at DESC").Limit(longestList)
	case showCancelled:
		query = query.Where("bookings.cancelled = ?", true).
			Order("bookings.starts_at DESC").Limit(longestList)
	default:
		query = query.Where("bookings.cancelled = ? AND "+
			"bookings.ends_at > ?", false, now.UTC()).
			Order("bookings.starts_at")
	}
	var lines []BookingLine
	err := query.Scan(&lines).Error
	return lines, err
}

func (bookings Bookings) lines(ctx context.Context) *gorm.DB {
	return bookings.database.WithContext(ctx).Model(&Booking{}).
		Select("bookings.*, services.name AS service_name").
		Joins("LEFT JOIN services ON services.id = bookings.service_id")
}

// bookView reads ?show=. An unknown value is an old or hand-typed link,
// so it shows the upcoming list rather than an error.
func bookView(value string) string {
	switch value {
	case showPast, showCancelled:
		return value
	}
	return showUpcoming
}

