// internal/groomer/owner.go
// byDay groups bookings, already in order, under their salon day.
func byDay(list []Booking) []bookingDay {
	var days []bookingDay
	for _, booking := range list {
		day := longDay(booking.StartsAt)
		if len(days) == 0 || days[len(days)-1].Day != day {
			days = append(days, bookingDay{Day: day})
		}
		row := bookingRow{Href: bookingPath(booking.ID),
			Main: shortTime(booking.StartsAt) + " · " + booking.DogName,
			Sub: booking.ServiceName + " for " + booking.CustomerName +
				", " + booking.Phone,
			Status: "Booked", Tone: "positive"}
		if booking.CancelledAt != nil {
			row.Status, row.Tone = "Cancelled", "negative"
		}
		last := &days[len(days)-1]
		last.Rows = append(last.Rows, row)
	}
	return days
}

