// internal/groomer/ledger.go
// Upcoming is every booking from the start of today on, soonest first,
// cancelled ones included so the owner can see what changed.
func (salon *Salon) Upcoming(ctx context.Context) ([]BookingView, error) {
	today := midnight(salon.Now()).UTC()
	return salon.views(ctx, func(query *gorm.DB) *gorm.DB {
		return query.Where("starts_at >= ?", today).Order("starts_at")
	})
}

// Past is every booking before today, latest first.
func (salon *Salon) Past(ctx context.Context) ([]BookingView, error) {
	today := midnight(salon.Now()).UTC()
	return salon.views(ctx, func(query *gorm.DB) *gorm.DB {
		return query.Where("starts_at < ?", today).Order("starts_at desc")
	})
}

func (salon *Salon) views(
	ctx context.Context, narrow func(*gorm.DB) *gorm.DB,
) ([]BookingView, error) {
	var bookings []Booking
	query := narrow(salon.database.WithContext(ctx)).Limit(listLimit)
	if err := query.Find(&bookings).Error; err != nil {
		return nil, err
	}
	services, err := salon.AllServices(ctx)
	if err != nil {
		return nil, err
	}
	byID := map[int64]Service{}
	for _, service := range services {
		byID[service.ID] = service
	}
	views := make([]BookingView, 0, len(bookings))
	for _, booking := range bookings {
		views = append(views, BookingView{booking, byID[booking.ServiceID]})
	}
	return views, nil
}

