// internal/groomer/hours.go
// Set changes one day's hours. A closed day keeps the times it had, so
// opening it again later starts from the hours it used to keep.
func (hours *Hours) Set(ctx context.Context, day OpeningDay) error {
	if day.Weekday < 0 || day.Weekday > 6 {
		return op.NotFound{}
	}
	if day.Open && day.Closes <= day.Opens {
		return op.Invalid{Fields: map[string]string{
			"Closes": "Closing time must be after opening time.",
		}}
	}
	current, err := hours.On(ctx, time.Weekday(day.Weekday))
	if err != nil {
		return err
	}
	if !day.Open {
		day.Opens, day.Closes = current.Opens, current.Closes
	}
	day.ID = current.ID
	if day.ID == 0 {
		return hours.database.WithContext(ctx).Create(&day).Error
	}
	return hours.database.WithContext(ctx).Model(&day).
		Select("Open", "Opens", "Closes").Updates(&day).Error
}

