// internal/groomer/salon.go
// SetWeek replaces the opening hours for all seven days at once.
func (salon salon) SetWeek(ctx context.Context, week [7]OpeningDay) error {
	fields := map[string]string{}
	for day, hours := range week {
		if hours.Open && hours.ClosesAt <= hours.OpensAt {
			fields[dayField(day)] = "Closing time must be after opening."
		}
	}
	if len(fields) > 0 {
		return op.Invalid{Fields: fields}
	}
	return salon.database.WithContext(ctx).Transaction(
		func(tx *gorm.DB) error {
			for day, hours := range week {
				if err := saveDay(tx, day, hours); err != nil {
					return err
				}
			}
			return nil
		})
}

func saveDay(tx *gorm.DB, day int, hours OpeningDay) error {
	row := OpeningDay{Weekday: day}
	if err := tx.Where("weekday = ?", day).FirstOrCreate(&row).
		Error; err != nil {
		return err
	}
	return tx.Model(&row).Select("Open", "OpensAt", "ClosesAt").
		Updates(OpeningDay{Open: hours.Open, OpensAt: hours.OpensAt,
			ClosesAt: hours.ClosesAt}).Error
}

