// validPhone accepts what people write a phone number with: digits,
// spaces, dashes, brackets and a leading plus, with 7 to 15 digits.
func validPhone(phone string) bool {
	digits := 0
	for _, char := range strings.TrimSpace(phone) {
		switch {
		case char >= '0' && char <= '9':
			digits++
		case !strings.ContainsRune("+ -()", char):
			return false
		}
	}
	return digits >= 7 && digits <= 15
}

