func (bookings *Bookings) stillFree(
	ctx context.Context, tx *gorm.DB, request Request,
) bool {
	day := localDay(request.StartsAt)
	if !bookings.inWindow(day) {
		return false
	}
	plan, err := loadSchedule(ctx, tx, bookings.now(),
		day, day.AddDate(0, 0, 1))
	if err != nil {
		return false
	}
	free := plan.freeOn(request.Service, day)
	return slices.ContainsFunc(free, request.StartsAt.Equal)
}

func (request *Request) check() error {
	request.CustomerName = strings.TrimSpace(request.CustomerName)
	request.Phone = strings.TrimSpace(request.Phone)
	request.DogName = strings.TrimSpace(request.DogName)
	request.Notes = strings.TrimSpace(request.Notes)
	problems := map[string]string{}
	if request.CustomerName == "" || len(request.CustomerName) > 80 {
		problems["CustomerName"] = "Enter your name."
	}
	if !validPhone(request.Phone) {
		problems["Phone"] = "Enter a phone number we can call, " +
			"such as 07700 900123."
	}
	if request.DogName == "" || len(request.DogName) > 40 {
		problems["DogName"] = "Enter your dog's name."
	}
	if len(request.Notes) > 500 {
		problems["Notes"] = "Keep notes under 500 characters."
	}
	if len(problems) > 0 {
		return op.Invalid{Fields: problems}
	}
	return nil
}

// validPhone accepts the ways people write phone numbers: digits with
// spaces, dashes, dots, brackets and a leading plus.
func validPhone(phone string) bool {
	digits := 0
	for index, char := range phone {
		switch {
		case char >= '0' && char <= '9':
			digits++
		case char == '+' && index == 0:
		case strings.ContainsRune(" -.()", char):
		default:
			return false
		}
	}
	return digits >= 7 && digits <= 15
}

