// internal/groomer/services.go
// SetHours changes one weekday's opening hours. Bookings already made
// stand: the owner cancels any that no longer fit.
func (salon salon) SetHours(ctx context.Context, weekday int,
	input hoursInput) error {
	if weekday < 0 || weekday > 6 {
		return op.NotFound{}
	}
	if problems := input.problems(); len(problems) > 0 {
		return op.Invalid{Fields: problems}
	}
	columns := []string{"Open", "UpdatedAt"}
	if input.OpensAt >= 0 && input.ClosesAt >= 0 {
		columns = append(columns, "OpensAt", "ClosesAt")
	}
	return salon.database.WithContext(ctx).Transaction(
		func(transaction *gorm.DB) error {
			hours := OpeningHours{Weekday: weekday}
			err := transaction.Where("weekday = ?", weekday).
				FirstOrCreate(&hours).Error
			if err != nil {
				return err
			}
			return transaction.Model(&hours).Select(columns).
				Updates(OpeningHours{Open: input.Open,
					OpensAt: input.OpensAt, ClosesAt: input.ClosesAt}).Error
		})
}

func (input hoursInput) problems() map[string]string {
	problems := map[string]string{}
	switch {
	case !input.Open && (input.OpensAt < 0) != (input.ClosesAt < 0):
		problems["closes"] = "Give both times, or neither."
	case !input.Open:
	case input.OpensAt < 0:
		problems["opens"] = "Enter the time you open."
	case input.ClosesAt < 0:
		problems["closes"] = "Enter the time you close."
	case input.ClosesAt <= input.OpensAt:
		problems["closes"] = "Closing time must be after opening time."
	}
	if input.OpensAt >= 0 && input.ClosesAt > input.OpensAt &&
		input.ClosesAt-input.OpensAt < 15 {
		problems["closes"] = "Stay open at least 15 minutes."
	}
	return problems
}

Right.Text:
// internal/groomer/hours.go
// Save replaces the whole week. Bookings already made are kept even
// when they now fall outside the hours; the owner sees them and
// decides.
func (hours *openingHours) Save(
	ctx context.Context, week []OpeningDay,
) error {
	if err := checkWeek(week); err != nil {
		return err
	}
	rows := make([]OpeningDay, 0, len(week))
	for _, day := range week {
		day.ID = 0
		rows = append(rows, day)
	}
	changed := []string{"open", "opens", "closes"}
	return hours.database.WithContext(ctx).Clauses(clause.OnConflict{
		Columns:   []clause.Column{{Name: "weekday"}},
		DoUpdates: clause.AssignmentColumns(changed),
	}).Create(&rows).Error
}

func checkWeek(week []OpeningDay) error {
	problems := map[string]string{}
	for _, day := range week {
		if !day.Open {
			continue
		}
		name := time.Weekday(day.Weekday).String()
		if day.Closes <= day.Opens {
			problems[name+"Closes"] = "Closing time must be after " +
				"opening time."
		}
	}
	if len(problems) > 0 {
		return op.Invalid{Fields: problems}
	}
	return nil
}

