// internal/groomer/bookings.go
// bookings is one of the owner's lists: upcoming soonest first, the
// others most recent first, each capped so a busy year stays quick.
func (salon salon) bookings(ctx context.Context, list bookingList,
	now time.Time) ([]Booking, error) {
	query := salon.database.WithContext(ctx).Preload("Service").Limit(200)
	today := midnight(now, salon.zone).UTC()
	switch list {
	case pastBookings:
		query = query.Where("cancelled_at IS NULL AND starts_at < ?",
			today).Order("starts_at DESC")
	case cancelledBookings:
		query = query.Where("cancelled_at IS NOT NULL").
			Order("starts_at DESC")
	default:
		query = query.Where("cancelled_at IS NULL AND starts_at >= ?",
			today).Order("starts_at")
	}
	var bookings []Booking
	err := query.Find(&bookings).Error
	for index := range bookings {
		bookings[index] = salon.local(bookings[index])
	}
	return bookings, err
}

