// internal/groomer/bookings.go
// checked trims what the customer typed and refuses what the salon
// could not use to reach them.
func (who customer) checked() (customer, error) {
	who.Name = strings.TrimSpace(who.Name)
	who.Phone = strings.TrimSpace(who.Phone)
	who.DogName = strings.TrimSpace(who.DogName)
	fields := map[string]string{}
	if who.Name == "" || len(who.Name) > 80 {
		fields["Name"] = "Enter your name, up to 80 characters."
	}
	if !phoneLike(who.Phone) {
		fields["Phone"] = "Enter a phone number we can call, like " +
			"07700 900123."
	}
	if who.DogName == "" || len(who.DogName) > 40 {
		fields["DogName"] = "Enter your dog's name, up to 40 characters."
	}
	if len(fields) > 0 {
		return who, op.Invalid{Fields: fields}
	}
	return who, nil
}

// phoneLike accepts 7 to 15 digits with the spacing and punctuation
// people write phone numbers with, and nothing else.
func phoneLike(phone string) bool {
	digits := 0
	for _, character := range phone {
		switch {
		case unicode.IsDigit(character):
			digits++
		case !strings.ContainsRune(" +-().", character):
			return false
		}
	}
	return digits >= 7 && digits <= 15
}

// internal/groomer/calendar.go
// IsFree reports whether service can start at starts: on the grid,
// inside opening hours, in the window and clear of every booking.
func (calendar calendar) IsFree(ctx context.Context, service Service,
	starts time.Time) (bool, error) {
	slots, err := calendar.Slots(ctx, service, calendar.dateOf(starts))
	for _, slot := range slots {
		if slot.Equal(starts) {
			return true, err
		}
	}
	return false, err
}

