// internal/groomer/bookings.go
func (request bookingRequest) check() error {
	problems := map[string]string{}
	if request.CustomerName == "" {
		problems["CustomerName"] = "Enter your name."
	}
	if request.DogName == "" {
		problems["DogName"] = "Enter your dog's name."
	}
	if !plausiblePhone(request.Phone) {
		problems["Phone"] = "Enter a phone number we can call, " +
			"such as 07700 900123."
	}
	if len(problems) > 0 {
		return op.Invalid{Fields: problems}
	}
	return nil
}

// plausiblePhone accepts the ways people write a number: digits with
// spaces, dashes, brackets and a leading plus, seven digits or more.
func plausiblePhone(phone string) bool {
	digits := 0
	for index, character := range phone {
		switch {
		case unicode.IsDigit(character):
			digits++
		case character == '+' && index == 0:
		case strings.ContainsRune(" -().", character):
		default:
			return false
		}
	}
	return digits >= 7 && digits <= 15
}

