func (bookings bookings) Cancel(ctx context.Context, id int64) error {
	now := bookings.calendar.now().UTC()
	result := live(bookings.calendar.database.WithContext(ctx).
		Model(&Booking{})).Where("id = ? AND ends_at > ?", id, now).
		Select("CancelledAt").Updates(map[string]any{"CancelledAt": now})
	if result.Error != nil || result.RowsAffected > 0 {
		return result.Error
