// internal/groomer/hours.go
// Set stores one weekday's hours. Bookings already made on that day
// stand: the owner can cancel them one by one if the salon now closes.
func (hours *Hours) Set(
	ctx context.Context, weekday int, input hoursInput,
) error {
	if weekday < 0 || weekday > 6 {
		return op.NotFound{}
	}
	if err := input.check(); err != nil {
		return err
	}
	return hours.database.WithContext(ctx).Transaction(
		func(tx *gorm.DB) error {
			return saveDay(tx, weekday, input)
		})
}

func saveDay(tx *gorm.DB, weekday int, input hoursInput) error {
	var day OpeningDay
	err := tx.Where("weekday = ?", weekday).First(&day).Error
	if errors.Is(err, gorm.ErrRecordNotFound) {
		return tx.Create(&OpeningDay{Weekday: weekday, Open: input.Open,
			Opens: input.Opens, Closes: input.Closes}).Error
	}
	if err != nil {
		return err
	}
	return tx.Model(&day).Select("Open", "Opens", "Closes").
		Updates(map[string]any{"Open": input.Open,
			"Opens": input.Opens, "Closes": input.Closes}).Error
}

func (input hoursInput) check() error {
	if !input.Open {
		return nil
	}
	problems := map[string]string{}
	if !input.OpensSet {
		problems["Opens"] = "Enter the opening time."
	}
	if !input.ClosesSet {
		problems["Closes"] = "Enter the closing time."
	}
	if len(problems) == 0 && input.Closes <= input.Opens {
		problems["Closes"] = "Closing time must be after opening time."
	}
	if len(problems) > 0 {
		return op.Invalid{Fields: problems}
	}
	return nil
}

