// internal/groomer/bookings.go
// Upcoming lists bookings from the start of today on, soonest first.
func (salon *Salon) Upcoming(ctx context.Context) ([]BookingView, error) {
	today := startOfDay(salon.now().In(salon.location)).UTC()
	var views []BookingView
	err := salon.bookings(ctx).Where("bookings.starts_at >= ?", today).
		Order("bookings.starts_at").Find(&views).Error
	return salon.local(views), err
}

// Past lists the latest hundred bookings before today, newest first.
func (salon *Salon) Past(ctx context.Context) ([]BookingView, error) {
	today := startOfDay(salon.now().In(salon.location)).UTC()
	var views []BookingView
	err := salon.bookings(ctx).Where("bookings.starts_at < ?", today).
		Order("bookings.starts_at desc").Limit(100).Find(&views).Error
	return salon.local(views), err
}

func (salon *Salon) bookings(ctx context.Context) *gorm.DB {
	return salon.database.WithContext(ctx).Model(&Booking{}).
		Select("bookings.*, services.name AS service_name").
		Joins("JOIN services ON services.id = bookings.service_id")
}

// local moves each booking's times into the salon's zone for display.
func (salon *Salon) local(views []BookingView) []BookingView {
	for index := range views {
		views[index].StartsAt = views[index].StartsAt.In(salon.location)
		views[index].EndsAt = views[index].EndsAt.In(salon.location)
	}
	return views
}

