// internal/groomer/bookings.go
// Agenda is the owner's list of bookings: upcoming ones soonest first,
// past or cancelled ones latest first.
func (bookings bookings) Agenda(ctx context.Context, view string) (
	[]Booking, error) {
	now := bookings.schedule.now().UTC()
	query := bookings.database.WithContext(ctx).Preload("Service")
	switch view {
	case "past":
		query = query.Where("cancelled = ? AND starts_at < ?", false, now).
			Order("starts_at desc").Limit(200)
	case "cancelled":
		query = query.Where("cancelled = ?", true).
			Order("starts_at desc").Limit(200)
	default:
		query = query.Where("cancelled = ? AND ends_at >= ?", false, now).
			Order("starts_at")
	}
	var found []Booking
	err := query.Find(&found).Error
	return found, err
}

