// internal/groomer/hours.go
// Save replaces the opening times for all seven days at once, so the
// week is never half-saved.
func (hours hours) Save(ctx context.Context, days week) error {
	if err := days.check(); err != nil {
		return err
	}
	return hours.database.WithContext(ctx).Transaction(
		func(tx *gorm.DB) error {
			for _, day := range days {
				if err := saveDay(tx, day); err != nil {
					return err
				}
			}
			return nil
		})
}

func saveDay(tx *gorm.DB, day OpeningDay) error {
	result := tx.Model(&OpeningDay{}).Where("weekday = ?", day.Weekday).
		Select("Open", "Opens", "Closes").
		Updates(map[string]any{"Open": day.Open, "Opens": day.Opens,
			"Closes": day.Closes})
	if result.Error != nil || result.RowsAffected > 0 {
		return result.Error
	}
	row := OpeningDay{Weekday: day.Weekday, Open: day.Open,
		Opens: day.Opens, Closes: day.Closes}
	return tx.Create(&row).Error
}

// check refuses an open day that closes before it opens. A closed
// day's times are kept as typed, so reopening it later starts from
// them.
func (days week) check() error {
	fields := map[string]string{}
	for _, day := range days {
		if day.Open && day.Closes-day.Opens < 30 {
			fields[fmt.Sprintf("closes_%d", day.Weekday)] =
				"Close at least 30 minutes after opening."
		}
	}
	if len(fields) > 0 {
		return op.Invalid{Fields: fields}
	}
	return nil
}

