// internal/groomer/hours.go
// SetWeek replaces the opening hours. Bookings already made stand even
// where the salon now closes earlier: the owner cancels any that must go.
func (hours hours) SetWeek(ctx context.Context, days []OpeningDay) error {
	fields := map[string]string{}
	for _, day := range days {
		if day.Open && day.Opens >= day.Closes {
			fields[dayField(day.Weekday)] = "Closing time must be " +
				"after opening time."
		}
	}
	if len(fields) > 0 {
		return op.Invalid{Fields: fields}
	}
	return hours.database.WithContext(ctx).Transaction(
		func(tx *gorm.DB) error {
			for _, day := range days {
				err := tx.Clauses(clause.OnConflict{
					Columns: []clause.Column{{Name: "weekday"}},
					DoUpdates: clause.AssignmentColumns(
						[]string{"open", "opens", "closes"}),
				}).Create(&day).Error
				if err != nil {
					return err
				}
			}
			return nil
		})
}

