// internal/groomer/hours.go
// Save replaces the whole week. Bookings already made are kept even
// when they now fall outside the hours; the owner sees them and
// decides.
func (hours *openingHours) Save(
	ctx context.Context, week []OpeningDay,
) error {
	if err := checkWeek(week); err != nil {
		return err
	}
	rows := make([]OpeningDay, 0, len(week))
	for _, day := range week {
		day.ID = 0
		rows = append(rows, day)
	}
	changed := []string{"open", "opens", "closes"}
	return hours.database.WithContext(ctx).Clauses(clause.OnConflict{
		Columns:   []clause.Column{{Name: "weekday"}},
		DoUpdates: clause.AssignmentColumns(changed),
	}).Create(&rows).Error
}

func checkWeek(week []OpeningDay) error {
	problems := map[string]string{}
	for _, day := range week {
		if !day.Open {
			continue
		}
		name := time.Weekday(day.Weekday).String()
		if day.Closes <= day.Opens {
			problems[name+"Closes"] = "Closing time must be after " +
				"opening time."
		}
	}
	if len(problems) > 0 {
		return op.Invalid{Fields: problems}
	}
	return nil
}

