// internal/groomer/appointments.go
// List is the bookings in scope: upcoming soonest first, the rest
// most recent first.
func (book *diary) List(
	ctx context.Context, scope bookingScope,
) ([]appointment, error) {
	query := book.withService(ctx)
	now := book.now().UTC().Truncate(time.Second)
	switch scope {
	case scopePast:
		query = query.Where("bookings.cancelled = ? AND "+
			"bookings.ends_at <= ?", false, now).
			Order("bookings.starts_at DESC")
	case scopeCancelled:
		query = query.Where("bookings.cancelled = ?", true).
			Order("bookings.starts_at DESC")
	default:
		query = query.Where("bookings.cancelled = ? AND "+
			"bookings.ends_at > ?", false, now).
			Order("bookings.starts_at")
	}
	var found []appointment
	err := query.Limit(200).Find(&found).Error
	return found, err
}

func (book *diary) withService(ctx context.Context) *gorm.DB {
	return book.database.WithContext(ctx).Model(&Booking{}).
		Select("bookings.*, services.name AS service_name").
		Joins("LEFT JOIN services ON services.id = bookings.service_id")
}

