// internal/groomer/services.go
// Change rewrites a service's details. Bookings already made keep the
// name and length they were made with.
func (services services) Change(ctx context.Context, id int64,
	input serviceInput) error {
	input, err := input.checked()
	if err != nil {
		return err
	}
	result := services.database.WithContext(ctx).Model(&Service{ID: id}).
		Select("Name", "Description", "Minutes", "PriceMinor",
			"Currency", "Offered", "UpdatedAt").
		Updates(map[string]any{"Name": input.Name,
			"Description": input.Description, "Minutes": input.Minutes,
			"PriceMinor": input.PriceMinor, "Currency": salonCurrency,
			"Offered": input.Offered})
	if result.Error != nil {
		return result.Error
	}
	if result.RowsAffected == 0 {
		return op.NotFound{}
	}
	return nil
}

// checked trims the input and refuses what the menu cannot show.
func (input serviceInput) checked() (serviceInput, error) {
	input.Name = strings.TrimSpace(input.Name)
	input.Description = strings.TrimSpace(input.Description)
	fields := map[string]string{}
	if input.Name == "" || len(input.Name) > 80 {
		fields["Name"] = "Enter a name of up to 80 characters."
	}
	if len(input.Description) > 400 {
		fields["Description"] = "Keep the description under 400 characters."
	}
	if !slices.Contains(serviceLengths, input.Minutes) {
		fields["Minutes"] = "Choose how long the appointment takes."
	}
	if input.PriceMinor < 0 {
		fields["Price"] = "Enter a price of 0 or more."
	}
	if len(fields) > 0 {
		return input, op.Invalid{Fields: fields}
	}
	return input, nil
}

