// internal/groomer/services.go
// Change rewrites a service. Bookings already made keep their own end
// time, so a new length applies to new bookings only.
func (services services) Change(ctx context.Context, id int64,
	input ServiceInput) error {
	if err := input.check(); err != nil {
		return err
	}
	result := services.database.WithContext(ctx).
		Model(&Service{ID: id}).
		Select("Name", "Description", "Minutes", "PriceMinor", "Offered",
			"UpdatedAt").
		Updates(map[string]any{
			"Name":        strings.TrimSpace(input.Name),
			"Description": strings.TrimSpace(input.Description),
			"Minutes":     input.Minutes, "PriceMinor": input.PriceMinor,
			"Offered": input.Offered, "UpdatedAt": services.now(),
		})
	if result.Error != nil {
		return result.Error
	}
	if result.RowsAffected == 0 {
		return op.NotFound{}
	}
	return nil
}

func (input ServiceInput) check() error {
	if fields := input.problems(); len(fields) > 0 {
		return op.Invalid{Fields: fields}
	}
	return nil
}

// problems is what is wrong with the input, by field.
func (input ServiceInput) problems() map[string]string {
	fields := map[string]string{}
	name := strings.TrimSpace(input.Name)
	if name == "" || len(name) > 60 {
		fields["Name"] = "Enter a name, up to 60 characters."
	}
	if len(input.Description) > 300 {
		fields["Description"] = "Keep the description to 300 characters."
	}
	if input.Minutes < 15 || input.Minutes > 480 || input.Minutes%15 != 0 {
		fields["Minutes"] = "Enter a length from 15 to 480 minutes, " +
			"in steps of 15."
	}
	if input.PriceMinor < 0 {
		fields["Price"] = "A price cannot be below zero."
	}
	return fields
}
